/// DC CGDSW (DC CGDSW)
fn a762(c: &mut dyn Context, m: u64) -> Result<Effect, Effect> {
    let _ = m;
    if !(c.implemented(Feature::FEAT_MTE2)?) {
        return Ok(Effect::Undefined);
    }
    if (at_el0_in_host(c)) || (at_el0_not_in_host(c)) {
        return Ok(Effect::Undefined);
    }
    if (c.el()) == (1) {
        if ((bits(c.read(Register::HCR_EL2, 0), 22, 1)) & 0x1) == 0x1 {
            return Ok(Effect::Trap {
                el: 2 as u8,
                ec: 24u64,
            });
        }
        if (c.implemented(Feature::FEAT_FGT)?)
            && (((bits(c.read(Register::HFGITR_EL2, 0), 5, 1)) & 0x1) == 0x1)
        {
            return Ok(Effect::Trap {
                el: 2 as u8,
                ec: 24u64,
            });
        }
        {
            let operation = Operation::Dc {
                kind: CacheType::DataTag,
                op: CacheOp::Clean,
                scope: CacheScope::SetWay,
                operand: c.x(),
            };
            c.operation(operation)?;
        }
        return Ok(Effect::Done);
    }
    if (c.el()) == (2) {
        {
            let operation = Operation::Dc {
                kind: CacheType::DataTag,
                op: CacheOp::Clean,
                scope: CacheScope::SetWay,
                operand: c.x(),
            };
            c.operation(operation)?;
        }
        return Ok(Effect::Done);
    }
    Ok(Effect::Refused("no AARCHMRS case applies"))
}

